package com.travelguide.entity;

import jakarta.persistence.*;

import java.time.LocalDateTime;

@Entity
@Table(name = "playback_logs", indexes = {
        @Index(name = "idx_playback_device", columnList = "device_id"),
        @Index(name = "idx_playback_poi", columnList = "poi_id"),
        @Index(name = "idx_playback_start", columnList = "start_time"),
        @Index(name = "idx_playback_trigger", columnList = "trigger_type"),
        @Index(name = "idx_playback_qr", columnList = "qr_id")
})
public class PlaybackLog {

    /** UUID generated by the app, used for idempotent batch uploads. */
    @Id
    @Column(length = 64)
    private String id;

    @Column(name = "device_id", nullable = false, length = 64)
    private String deviceId;

    @Column(name = "poi_id", nullable = false)
    private Long poiId;

    @Enumerated(EnumType.STRING)
    @Column(name = "trigger_type", nullable = false, length = 20)
    private TriggerType triggerType;

    @Enumerated(EnumType.STRING)
    @Column(name = "audio_mode", nullable = false, length = 20)
    private AudioMode audioMode;

    @Column(name = "language_code", nullable = false, length = 10)
    private String languageCode;

    @Column(name = "qr_code", length = 32)
    private String qrCode;

    @Column(name = "qr_id")
    private Long qrId;

    @Column(name = "bus_stop_id")
    private Long busStopId;

    @Column(name = "start_time", nullable = false)
    private LocalDateTime startTime;

    @Column(name = "end_time")
    private LocalDateTime endTime;

    @Column(name = "listened_seconds", nullable = false)
    private int listenedSeconds;

    @Column(name = "is_completed", nullable = false)
    private boolean completed;

    /** listened_seconds >= min_valid_listen_seconds (PRD definition). */
    @Column(name = "valid_listen", nullable = false)
    private boolean validListen;

    @Column(nullable = false)
    private LocalDateTime createdAt = LocalDateTime.now();

    public String getId() { return id; }
    public void setId(String id) { this.id = id; }
    public String getDeviceId() { return deviceId; }
    public void setDeviceId(String deviceId) { this.deviceId = deviceId; }
    public Long getPoiId() { return poiId; }
    public void setPoiId(Long poiId) { this.poiId = poiId; }
    public TriggerType getTriggerType() { return triggerType; }
    public void setTriggerType(TriggerType triggerType) { this.triggerType = triggerType; }
    public AudioMode getAudioMode() { return audioMode; }
    public void setAudioMode(AudioMode audioMode) { this.audioMode = audioMode; }
    public String getLanguageCode() { return languageCode; }
    public void setLanguageCode(String languageCode) { this.languageCode = languageCode; }
    public String getQrCode() { return qrCode; }
    public void setQrCode(String qrCode) { this.qrCode = qrCode; }
    public Long getQrId() { return qrId; }
    public void setQrId(Long qrId) { this.qrId = qrId; }
    public Long getBusStopId() { return busStopId; }
    public void setBusStopId(Long busStopId) { this.busStopId = busStopId; }
    public LocalDateTime getStartTime() { return startTime; }
    public void setStartTime(LocalDateTime startTime) { this.startTime = startTime; }
    public LocalDateTime getEndTime() { return endTime; }
    public void setEndTime(LocalDateTime endTime) { this.endTime = endTime; }
    public int getListenedSeconds() { return listenedSeconds; }
    public void setListenedSeconds(int listenedSeconds) { this.listenedSeconds = listenedSeconds; }
    public boolean isCompleted() { return completed; }
    public void setCompleted(boolean completed) { this.completed = completed; }
    public boolean isValidListen() { return validListen; }
    public void setValidListen(boolean validListen) { this.validListen = validListen; }
    public LocalDateTime getCreatedAt() { return createdAt; }
}
